    /**
     * Service version {@code 2026-01-01-preview}.
     */
    V2026_01_01_PREVIEW("2026-01-01-preview");

    private final String version;

    CryptographyServiceVersion(String version) {
        this.version = version;
    }

    /**
     * {@inheritDoc}
